// ====================================
// CONFIGURACIÓN
// ====================================
const CONFIG = {
  HORA_APERTURA: "08:00",
  HORA_CIERRE: "18:00",
  ALMUERZO_INICIO: "12:00",
  ALMUERZO_FIN: "13:00",
  BREAK_INICIO: "10:30",
  BREAK_FIN: "10:45",
  TIEMPO_LLEGADA_CLIENTE: 15,
  TIEMPO_LAVADO: 30,
  TIEMPO_ENTREGA: 15,
  MIN_HORAS_TURNO: 18,
  DIAS_ADELANTE: 30,
  DIAS_LABORALES: [1,2,3,4,5]
};

const OFFSET = "-03:00";
const TIMEZONE = "America/Argentina/Buenos_Aires";

// ====================================
// UTILIDADES
// ====================================

function formatearFechaISO(d){
  return d.toLocaleDateString("en-CA",{timeZone:TIMEZONE});
}

function formatearHora(d){
  return d.toLocaleTimeString("en-GB",{
    timeZone:TIMEZONE,
    hour:"2-digit",
    minute:"2-digit",
    hour12:false
  });
}

function obtenerDiaSemana(d){
  return d.toLocaleDateString("es-AR",{timeZone:TIMEZONE,weekday:"long"})
  .replace(/^\w/,c=>c.toUpperCase());
}

// ====================================
// CALCULAR FIN CON BREAKS
// ====================================

function calcularFinConBreaks(inicioDate,duracionMin,fechaStr){

  let actual = new Date(inicioDate.getTime());
  let restantes = duracionMin;
  let duracionTotalReal = 0;

  const b_inicio = new Date(`${fechaStr}T${CONFIG.BREAK_INICIO}:00${OFFSET}`).getTime();
  const b_fin = new Date(`${fechaStr}T${CONFIG.BREAK_FIN}:00${OFFSET}`).getTime();
  const a_inicio = new Date(`${fechaStr}T${CONFIG.ALMUERZO_INICIO}:00${OFFSET}`).getTime();
  const a_fin = new Date(`${fechaStr}T${CONFIG.ALMUERZO_FIN}:00${OFFSET}`).getTime();

  while(restantes>0){

    const t = actual.getTime();

    if(t>=b_inicio && t<b_fin){
      const salto=(b_fin-t)/60000;
      actual.setMinutes(actual.getMinutes()+salto);
      duracionTotalReal+=salto;
    }

    else if(t>=a_inicio && t<a_fin){
      const salto=(a_fin-t)/60000;
      actual.setMinutes(actual.getMinutes()+salto);
      duracionTotalReal+=salto;
    }

    else{
      actual.setMinutes(actual.getMinutes()+1);
      restantes--;
      duracionTotalReal++;
    }

    if(duracionTotalReal>720) break;
  }

  return {horaFin:actual,duracionTotal:duracionTotalReal};
}

// ====================================
// PARSE INPUT EVENTS
// ====================================

const eventosPorDia = {};

for(const item of $input.all()){

  const fecha = item.json.date;
  const eventos = item.json.events || [];

  eventosPorDia[fecha] = eventos.map(e=>({

    inicio:new Date(`${fecha}T${e.start}:00${OFFSET}`),
    fin:new Date(`${fecha}T${e.end}:00${OFFSET}`)

  }));

}

// ====================================
// PROCESO PRINCIPAL
// ====================================

const ahora = new Date();
const fechaMinimaParaTurno =
new Date(ahora.getTime()+CONFIG.MIN_HORAS_TURNO*3600000);

const duracionTotalServicio =
45 + CONFIG.TIEMPO_LAVADO + CONFIG.TIEMPO_ENTREGA;

let todosLosSlots = [];

for(let i=0;i<=CONFIG.DIAS_ADELANTE;i++){

  const fechaEvaluar = new Date();
  fechaEvaluar.setDate(ahora.getDate()+i);

  if(!CONFIG.DIAS_LABORALES.includes(fechaEvaluar.getDay()))
  continue;

  const fechaStr = formatearFechaISO(fechaEvaluar);

  const apertura =
  new Date(`${fechaStr}T${CONFIG.HORA_APERTURA}:00${OFFSET}`);

  const cierre =
  new Date(`${fechaStr}T${CONFIG.HORA_CIERRE}:00${OFFSET}`);

  // BREAKS (calculated once per day)
  const breakInicio = new Date(`${fechaStr}T${CONFIG.BREAK_INICIO}:00${OFFSET}`).getTime();
  const breakFin = new Date(`${fechaStr}T${CONFIG.BREAK_FIN}:00${OFFSET}`).getTime();

  const almuerzoInicio = new Date(`${fechaStr}T${CONFIG.ALMUERZO_INICIO}:00${OFFSET}`).getTime();
  const almuerzoFin = new Date(`${fechaStr}T${CONFIG.ALMUERZO_FIN}:00${OFFSET}`).getTime();

  let actualInicio =
  new Date(apertura.getTime()+CONFIG.TIEMPO_LLEGADA_CLIENTE*60000);

  if(actualInicio<fechaMinimaParaTurno){

    actualInicio = new Date(fechaMinimaParaTurno.getTime());

    actualInicio.setMinutes(
      Math.ceil(actualInicio.getMinutes()/15)*15,
      0,
      0
    );

  }

  const eventosDelDia = eventosPorDia[fechaStr] || [];

  while(actualInicio<cierre){

    const tInicio = actualInicio.getTime();

    // ❌ BLOCK START DURING BREAKS
    if(
      (tInicio>=breakInicio && tInicio<breakFin) ||
      (tInicio>=almuerzoInicio && tInicio<almuerzoFin)
    ){
      actualInicio.setMinutes(actualInicio.getMinutes()+15);
      continue;
    }

    const {horaFin,duracionTotal} =
    calcularFinConBreaks(actualInicio,duracionTotalServicio,fechaStr);

    if(horaFin>cierre) break;

    const tFin = horaFin.getTime();

    const tieneConflicto = eventosDelDia.some(e=>
      (tInicio<e.fin.getTime() && tFin>e.inicio.getTime())
    );

    if(!tieneConflicto){

      todosLosSlots.push({

        fecha:fechaStr,

        dia_semana:obtenerDiaSemana(fechaEvaluar),

        FechaFormato:
        `${obtenerDiaSemana(fechaEvaluar)} ${fechaEvaluar.toLocaleDateString("es-AR")}`,

        hora_cliente:formatearHora(actualInicio),

        hora_real_inicio:formatearHora(actualInicio),

        hora_real_fin:formatearHora(horaFin),

        duracion_total:
        `${Math.floor(duracionTotal/60)}h ${Math.round(duracionTotal%60)}min`

      });

    }

    actualInicio.setMinutes(actualInicio.getMinutes()+15);

  }

}

// ====================================
// FILTRADO FINAL
// ====================================

const resultadoFinal = [];
const contadorPorDia = {};

for(const slot of todosLosSlots){

  if(resultadoFinal.length>=12) break;

  contadorPorDia[slot.fecha] =
  contadorPorDia[slot.fecha] || 0;

  if(contadorPorDia[slot.fecha]<2){

    resultadoFinal.push(slot);
    contadorPorDia[slot.fecha]++;

  }

}

return {
  turnos_disponibles:resultadoFinal
};

const grouped = {};
const seen = new Set();

for (const item of $input.all()) {

  const event = item.json;

  if (!event.start?.dateTime || !event.end?.dateTime) continue;

  const date = event.start.dateTime.slice(0,10);
  const start = event.start.dateTime.slice(11,16);
  const end = event.end.dateTime.slice(11,16);
  const summary = event.summary || "";

  const key = `${date}_${start}_${end}_${summary}`;

  // skip duplicates
  if (seen.has(key)) continue;
  seen.add(key);

  if (!grouped[date]) {
    grouped[date] = [];
  }

  grouped[date].push({
    start,
    end,
    summary
  });
}

// sort days and events
return Object.keys(grouped)
.sort()
.map(date => ({
  json: {
    date,
    events: grouped[date].sort((a,b)=>a.start.localeCompare(b.start))
  }
}));

const CAL_1 = "a53b69d6815a2d4305369311426ce3576383afa505d99095c577f9646361a062@group.calendar.google.com";
const CAL_2 = "0f751483f68a57e4c868713ec1c383b71b89fb153ea5660874412d4d4c10709c@group.calendar.google.com";

let todos = [];
for (const item of $input.all()) {
  todos = todos.concat(item.json.turnosDisponibles || []);
}

// Deduplicar por dia+inicio+calendario
const vistos = new Set();
const unicos = todos.filter(t => {
  const key = `${t.dia}_${t.inicio}_${t.Id_Calendario}`;
  if (vistos.has(key)) return false;
  vistos.add(key);
  return true;
});

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

// Elegir UN turno por día (aleatorio dentro de cada día)
function elegirUnoPorDia(turnos) {
  const porDia = {};
  for (const t of turnos) {
    if (!porDia[t.dia]) porDia[t.dia] = [];
    porDia[t.dia].push(t);
  }
  // De cada día, elegir uno al azar
  return Object.values(porDia).map(grupo => {
    const shuffled = shuffle([...grupo]);
    return shuffled[0];
  });
}

const cal1Unicos = shuffle(elegirUnoPorDia(unicos.filter(t => t.Id_Calendario === CAL_1)));
const cal2Unicos = shuffle(elegirUnoPorDia(unicos.filter(t => t.Id_Calendario === CAL_2)));

// Tomar hasta 2 de cada calendario, garantizando días distintos
let resultado = [];
const diasUsados = new Set();

for (const t of [...cal1Unicos, ...cal2Unicos]) {
  if (resultado.length >= 4) break;
  if (!diasUsados.has(t.dia)) {
    resultado.push(t);
    diasUsados.add(t.dia);
  }
}

// Si no llegamos a 4, completar con turnos de días aún no usados
if (resultado.length < 4) {
  const restantes = shuffle(unicos.filter(t => !diasUsados.has(t.dia)));
  const restantesPorDia = elegirUnoPorDia(restantes);
  for (const t of shuffle(restantesPorDia)) {
    if (resultado.length >= 4) break;
    if (!diasUsados.has(t.dia)) {
      resultado.push(t);
      diasUsados.add(t.dia);
    }
  }
}

resultado.sort((a, b) =>
  a.dia === b.dia
    ? a.inicio.localeCompare(b.inicio)
    : new Date(a.dia) - new Date(b.dia)
);

return [{
  json: {
    turnosDisponibles: resultado.slice(0, 4),
    cantidad: resultado.slice(0, 4).length
  }
}];
